import { test, expect } from '@playwright/test';

test.describe('Payment Flow - Total Price Update', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('https://example.com/cart');
  });

  test('should update total price when quantity is increased', async ({ page }) => {
    await page.getByLabel('Quantity').fill('2');
    await page.getByRole('button', { name: 'Update' }).click();
    const totalPrice = await page.getByText('Total Price: $').innerText();
    expect(totalPrice).toBe('$40.00'); // Assuming the price for 2 items is $40.00
  });

  test('should update total price when quantity is decreased', async ({ page }) => {
    await page.getByLabel('Quantity').fill('1');
    await page.getByRole('button', { name: 'Update' }).click();
    const totalPrice = await page.getByText('Total Price: $').innerText();
    expect(totalPrice).toBe('$20.00'); // Assuming the price for 1 item is $20.00
  });
});
